func.func @main(%arg0: tensor<8x8x3x3xf32>, %arg1: tensor<8xf32>, %arg2: tensor<8xf32>, %arg3: tensor<8xf32>, %arg4: tensor<8x8x8x8xf32>) -> tensor<8x8x10x10xf32> {
  // Perform transposed convolution
  // ConvTranspose2d with kernel_size=3, stride=1, groups=8
  // Input: %arg4 shape (8, 8, 8, 8) - (batch, in_channels, height, width)
  // Weight: %arg0 shape (8, 8, 3, 3) - (in_channels, out_channels/groups, kernel_h, kernel_w)
  // Output shape should be (8, 8, 10, 10)

  %conv_out = stablehlo.convolution(%arg4, %arg0)
    dim_numbers = [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1],
    window = {stride = [1, 1], pad = [[0, 0], [0, 0]], lhs_dilate = [1, 1], rhs_dilate = [1, 1], reverse = [false, false]}
    batch_group_count = 1,
    feature_group_count = 8,
    precision = [DEFAULT, DEFAULT]
    : (tensor<8x8x8x8xf32>, tensor<8x8x3x3xf32>) -> tensor<8x8x10x10xf32>

  // Add bias
  %bias_broadcast = stablehlo.broadcast_in_dim(%arg1, dims = [1]) : (tensor<8xf32>) -> tensor<8x8x10x10xf32>
  %after_bias = stablehlo.add(%conv_out, %bias_broadcast) : tensor<8x8x10x10xf32>

  // Apply GELU activation
  // GELU(x) = x * Phi(x) where Phi is the cumulative distribution function of standard normal
  // Approximation: GELU(x) ≈ 0.5 * x * (1 + tanh(sqrt(2/π) * (x + 0.044715 * x^3)))
  // Using erf approximation: GELU(x) = x * 0.5 * (1 + erf(x / sqrt(2)))

  %sqrt_2 = stablehlo.constant dense<1.41421356> : tensor<f32>
  %half = stablehlo.constant dense<0.5> : tensor<f32>
  %one = stablehlo.constant dense<1.0> : tensor<f32>

  %sqrt_2_bcast = stablehlo.broadcast_in_dim(%sqrt_2, dims = []) : (tensor<f32>) -> tensor<8x8x10x10xf32>
  %half_bcast = stablehlo.broadcast_in_dim(%half, dims = []) : (tensor<f32>) -> tensor<8x8x10x10xf32>
  %one_bcast = stablehlo.broadcast_in_dim(%one, dims = []) : (tensor<f32>) -> tensor<8x8x10x10xf32>

  %x_div_sqrt2 = stablehlo.divide(%after_bias, %sqrt_2_bcast) : tensor<8x8x10x10xf32>
  %erf_result = stablehlo.erf(%x_div_sqrt2) : tensor<8x8x10x10xf32>
  %one_plus_erf = stablehlo.add(%one_bcast, %erf_result) : tensor<8x8x10x10xf32>
  %half_one_plus_erf = stablehlo.multiply(%half_bcast, %one_plus_erf) : tensor<8x8x10x10xf32>
  %gelu_out = stablehlo.multiply(%after_bias, %half_one_plus_erf) : tensor<8x8x10x10xf32>

  // Apply GroupNorm
  // GroupNorm with num_groups=8, num_channels=8
  // Input shape: (8, 8, 10, 10) - (batch, channels, height, width)
  // Reshape to (batch, num_groups, channels/num_groups, height, width) = (8, 8, 1, 10, 10)

  %reshaped = stablehlo.reshape(%gelu_out) : (tensor<8x8x10x10xf32>) -> tensor<8x8x1x10x10xf32>

  // Compute mean and variance over (channels/num_groups, height, width) dimensions
  // Reduce over dimensions [2, 3, 4] to get shape (8, 8, 1, 1, 1)

  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = stablehlo.reduce(%reshaped init %zero) across dimensions = [2, 3, 4]
    : (tensor<8x8x1x10x10xf32>, tensor<f32>) -> tensor<8x8xf32>
    (%arg_mean: tensor<f32>, %arg_val: tensor<f32>) {
      %sum = stablehlo.add(%arg_mean, %arg_val) : tensor<f32>
      stablehlo.return(%sum) : tensor<f32>
    }

  // Divide by number of elements (1 * 10 * 10 = 100)
  %num_elements = stablehlo.constant dense<100.0> : tensor<f32>
  %num_elements_bcast = stablehlo.broadcast_in_dim(%num_elements, dims = []) : (tensor<f32>) -> tensor<8x8xf32>
  %mean_normalized = stablehlo.divide(%mean, %num_elements_bcast) : tensor<8x8xf32>

  % mean_reshaped = stablehlo.reshape(%mean_normalized) : (tensor<8x8xf32>) -> tensor<8x8x1x1x1xf32>
  %mean_bcast = stablehlo.broadcast_in_dim(%mean_reshaped, dims = [0, 1, 2, 3, 4]) : (tensor<8x8x1x1x1xf32>) -> tensor<8x8x1x10x10xf32>

  % centered = stablehlo.subtract(%reshaped, %mean_bcast) : tensor<8x8x1x10x10xf32>
