  %var_normalized = stablehlo.divide %var, %one_f_bcast : tensor<16x16xf32>

  % var_expanded = "stablehlo.reshape"(%var_normalized) : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  % eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<16x16x1xf32>
