  %padded_input = "stablehlo.pad"(%arg1) {
    edge_padding_low = array<i64: 0, 0, 2, 2, 2>,
    edge_padding_high = array<i64: 0, 0, 2, 2, 2>,
    interior_padding = array<i64: 0, 0, 0, 0, 0>
  } : (tensor<8x6x7x7x7xf32>) -> tensor<8x6x11x11x11xf32>

  // Step 4: Perform convolution
  // Input format: [batch, in_channels, d, h, w]
  // Kernel format: [out_channels, in_channels, kd, kh, kw]
  // Output format: [batch, out_channels, d, h, w]
  %result = "stablehlo.convolution"(%padded_input, %w_reversed) {
    window_strides = array<i64: 1, 1, 1>,
    padding = dense<[[0, 0], [0, 0], [0, 0]]> : tensor<3x2xi64>,
    lhs_dilation = array<i64: 1, 1, 1>,
    rhs_dilation = array<i64: 1, 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1, 2]x[o, i, 0, 1, 2]->[b, f, 0, 1, 2]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<8x6x11x11x11xf32>, tensor<6x6x3x3x3xf32>) -> tensor<8x6x9x9x9xf32>

  return %result : tensor<8x6x9x9x9xf32>
}

