func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
  // Convolution: input is NCHW (6x8x6x6), kernel is OIHW (7x8x3x3)
  // Output should be (6x7x4x4) with stride=1, no padding
  %conv_out = "stablehlo.convolution"(%arg4, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

  // Add bias: broadcast bias from (7,) to (6x7x4x4)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %conv_biased = stablehlo.add %conv_out, %bias_bcast : tensor<6x7x4x4xf32>

  // Batch Normalization in training mode
  // We need to compute mean and variance over batch and spatial dimensions (dims 0, 2, 3)
  // Keep feature dimension (dim 1)

  // Compute mean over dimensions [0, 2, 3]
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %mean_sum = "stablehlo.reduce"(%conv_biased, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>

  // Number of elements reduced: 6 * 4 * 4 = 96
  %num_elements = stablehlo.constant dense<96.0> : tensor<f32>
  %num_elements_bcast = "stablehlo.broadcast_in_dim"(%num_elements) {
    broadcast_dimensions = array<i64>
  } : (tensor<f32>) -> tensor<7xf32>
  %mean = stablehlo.divide %mean_sum, %num_elements_bcast : tensor<7xf32>

  // Compute variance: E[(x - mean)^2]
  % mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %centered = stablehlo.subtract %conv_biased, %mean_bcast : tensor<6x7x4x4xf32>
  %centered_sq = stablehlo.multiply %centered, %centered : tensor<6x7x4x4xf32>

  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%centered_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 0, 2, 3>} : (tensor<6x7x4x4xf32>, tensor<f32>) -> tensor<7xf32>

  %var = stablehlo.divide %var_sum, %num_elements_bcast : tensor<7xf32>

  % eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {
    broadcast_dimensions = array<i64>
  } : (tensor<f32>) -> tensor<7xf32>
  %var_plus_eps = stablehlo.add %var, %eps_bcast : tensor<7xf32>
  %std = stablehlo.sqrt %var_plus_eps : tensor<7xf32>

  % std_bcast = "stablehlo.broadcast_in_dim"(%std) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %normalized = stablehlo.divide %centered, %std_bcast : tensor<6x7x4x4xf32>

  % weight_bcast = "stablehlo.broadcast_in_dim"(%arg2) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %scaled = stablehlo.multiply %normalized, %weight_bcast : tensor<6x7x4x4xf32>

  % bias_bcast_bn = "stablehlo.broadcast_in_dim"(%arg3) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %bn_out = stablehlo.add %scaled, %bias_bcast_bn : tensor<6x7x4x4xf32>

  // Scale by 2.0
  %scaling_factor = stablehlo.constant dense<2.0> : tensor<f32>
  %scaling_factor_bcast = "stablehlo.broadcast_in_dim"(%scaling_factor) {
    broadcast_dimensions = array<i64>
  } : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %result = stablehlo.multiply %bn_out, %scaling_factor_bcast : tensor<6x7x4x4xf32>

  return %result : tensor<6x7x4x4xf32>
}

func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
  // Convolution: input is (6, 8, 6, 6), weight is (7, 8, 3, 3), output is (6, 7, 4, 4)
  %conv_out = stablehlo.convolution(%arg4, %arg0)
    dim_numbers = [b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1],
    window = {stride = [1, 1], pad = [[0, 0], [0, 0]], lhs_dilate = [1, 1], rhs_dilate = [1, 1]}
    : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

  // Add bias: broadcast bias (7,) to (6, 7, 4, 4)
  %bias_bcast = stablehlo.broadcast_in_dim(%arg1, dims = [1]) : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %conv_biased = stablehlo.add(%conv_out, %bias_bcast) : tensor<6x7x4x4xf32>

  // Batch Normalization in training mode
  // Compute mean and variance over batch and spatial dimensions (dims 0, 2, 3)
  // Shape: (6, 7, 4, 4) -> reduce over dims [0, 2, 3] -> (7,)

  // Compute mean
  %mean = stablehlo.reduce(%conv_biased init: %0 {
    ^bb0(%arg: f32, %acc: f32):
      %sum = stablehlo.add(%arg, %acc) : f32
      stablehlo.return(%sum) : f32
  }) across dimensions = [0, 2, 3] : (tensor<6x7x4x4xf32>) -> tensor<7xf32>

  %0 = stablehlo.constant dense<0.0> : tensor<f32>
  %count = stablehlo.constant dense<96.0> : tensor<f32>  // 6 * 4 * 4 = 96
  %count_bcast = stablehlo.broadcast_in_dim(%count, dims = []) : (tensor<f32>) -> tensor<7xf32>
  %mean_computed = stablehlo.divide(%mean, %count_bcast) : tensor<7xf32>

  // Compute variance: E[(x - mean)^2]
  %mean_bcast = stablehlo.broadcast_in_dim(%mean_computed, dims = [1]) : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %centered = stablehlo.subtract(%conv_biased, %mean_bcast) : tensor<6x7x4x4xf32>
  %centered_sq = stablehlo.multiply(%centered, %centered) : tensor<6x7x4x4xf32>

  %var_sum = stablehlo.reduce(%centered_sq init: %0 {
    ^bb0(%arg: f32, %acc: f32):
      %sum = stablehlo.add(%arg, %acc) : f32
      stablehlo.return(%sum) : f32
  }) across dimensions = [0, 2, 3] : (tensor<6x7x4x4xf32>) -> tensor<7xf32>

  %var = stablehlo.divide(%var_sum, %count_bcast) : tensor<7xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %eps_bcast = stablehlo.broadcast_in_dim(%eps, dims = []) : (tensor<f32>) -> tensor<7xf32>
  %var_plus_eps = stablehlo.add(%var, %eps_bcast) : tensor<7xf32>
  %std = stablehlo.sqrt(%var_plus_eps) : tensor<7xf32>

  %std_bcast = stablehlo.broadcast_in_dim(%std, dims = [1]) : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %normalized = stablehlo.divide(%centered, %std_bcast) : tensor<6x7x4x4xf32>

  // Scale and shift: y = gamma * normalized + beta
  %gamma_bcast = stablehlo.broadcast_in_dim(%arg2, dims = [1]) : (tensor<7xf32>) -> tensor<6x7x4x4xf32>
  %beta_bcast = stablehlo.broadcast_in_dim(%arg3, dims = [1]) : (tensor<7xf32>) -> tensor<6x7x4x4xf32>

  %scaled = stablehlo.multiply(%normalized, %gamma_bcast) : tensor<6x7x4x4xf32>
  %bn_out = stablehlo.add(%scaled, %beta_bcast) : tensor<6x7x4x4xf32>

  // Apply scaling factor: multiply by 2.0
  %scaling_factor = stablehlo.constant dense<2.0> : tensor<f32>
  %scaling_bcast = stablehlo.broadcast_in_dim(%scaling_factor, dims = []) : (tensor<f32>) -> tensor<6x7x4x4xf32>
  %result = stablehlo.multiply(%bn_out, %scaling_bcast) : tensor<6x7x4x4xf32>

  return %result : tensor<6x7x4x4xf32>
}

func.func @main(%arg0: tensor<7x8x3x3xf32>, %arg1: tensor<7xf32>, %arg2: tensor<7xf32>, %arg3: tensor<7xf32>, %arg4: tensor<6x8x6x6xf32>) -> tensor<6x7x4x4xf32> {
  // Convolution: input is NHWC format in PyTorch but stored as NCHW
  // arg4: tensor<6x8x6x6xf32> is (batch=6, channels=8, height=6, width=6)
  // arg0: tensor<7x8x3x3xf32> is (out_channels=7, in_channels=8, kh=3, kw=3)
  // Output should be (batch=6, out_channels=7, height=4, width=4)

  %conv_out = "stablehlo.convolution"(%arg4, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[0, 0], [0, 0]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 1, 1>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x8x6x6xf32>, tensor<7x8x3x3xf32>) -> tensor<6x7x4x4xf32>

  // Add bias: arg1 is tensor<7xf32>, need to broadcast to tensor<6x7x4x4xf32>
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>

  %conv_biased = stablehlo.add %conv_out, %bias_bcast : tensor<6x7x4x4xf32>

  // Batch Normalization
  // Reshape for reduce operations: (6, 7, 4, 4) -> (6, 7, 16)
  %reshaped = stablehlo.reshape %conv_biased : (tensor<6x7x4x4xf32>) -> tensor<6x7x16xf32>

  // Compute mean over spatial dimensions (dimension 2)
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_spatial = "stablehlo.reduce"(%reshaped, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<6x7x16xf32>, tensor<f32>) -> tensor<6x7xf32>

  %count = stablehlo.constant dense<16.0> : tensor<f32>
  %count_bcast = "stablehlo.broadcast_in_dim"(%count) {
    broadcast_dimensions = array<i64>
  } : (tensor<f32>) -> tensor<6x7xf32>

  %mean = stablehlo.divide %sum_spatial, %count_bcast : tensor<6x7xf32>

  // Compute variance: E[(x - mean)^2]
  %mean_bcast_for_var = "stablehlo.broadcast_in_dim"(%mean) {
    broadcast_dimensions = array<i64: 0, 1>
  } : (tensor<6x7xf32>) -> tensor<6x7x16xf32>

  %centered = stablehlo.subtract %reshaped, %mean_bcast_for_var : tensor<6x7x16xf32>
  %centered_sq = stablehlo.multiply %centered, %centered : tensor<6x7x16xf32>

  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %sum_var = "stablehlo.reduce"(%centered_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<6x7x16xf32>, tensor<f32>) -> tensor<6x7xf32>

  %variance = stablehlo.divide %sum_var, %count_bcast : tensor<6x7xf32>

  // Normalize: (x - mean) / sqrt(variance + eps)
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {
    broadcast_dimensions = array<i64>
  } : (tensor<f32>) -> tensor<6x7xf32>

  %var_plus_eps = stablehlo.add %variance, %eps_bcast : tensor<6x7xf32>
  %std = stablehlo.sqrt %var_plus_eps : tensor<6x7xf32>

  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {
    broadcast_dimensions = array<i64: 0, 1>
  } : (tensor<6x7xf32>) -> tensor<6x7x16xf32>

  %std_bcast = "stablehlo.broadcast_in_dim"(%std) {
    broadcast_dimensions = array<i64: 0, 1>
  } : (tensor<6x7xf32>) -> tensor<6x7x16xf32>

  %normalized = stablehlo.divide %centered, %std_bcast : tensor<6x7x16xf32>

  % Reshape back to (6, 7, 4, 4)
  %normalized_reshaped = stablehlo.reshape %normalized : (tensor<6x7x16xf32>) -> tensor<6x7x4x4xf32>

  % Apply scale (weight) and shift (bias)
  % arg2 is weight (scale), arg3 is bias (shift)
  %weight_bcast = "stablehlo.broadcast_in_dim"(%arg2) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<7xf32>) -> tensor<6x7x4x4xf32>

  %bias_bn_bcast = "stablehlo.broadcast_in_dim"(%arg3) {
    broadcast_dimensions = array<i64: 1>
