  // Compute (x - mean)
  %centered = stablehlo.subtract %arg0, %mean_bcast : tensor<6x7x8x8xf32>

  // Compute squared differences
  %centered_sq = stablehlo.multiply %centered, %centered : tensor<6x7x8x8xf32>

  // Compute variance (sum of squared differences)
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%centered_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add_result = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add_result) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x7x8x8xf32>, tensor<f32>) -> tensor<6x7xf32>

  // Reshape variance sum to (6, 7, 1, 1)
  %var_sum_reshaped = stablehlo.reshape %var_sum : (tensor<6x7xf32>) -> tensor<6x7x1x1xf32>

  // Compute variance by dividing by number of spatial elements
  %variance = stablehlo.divide %var_sum_reshaped, %num_elements : tensor<6x7x1x1xf32>

  // Broadcast variance to input shape
  %variance_bcast = "stablehlo.broadcast_in_dim"(%variance) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x7x1x1xf32>) -> tensor<6x7x8x8xf32>

