  // Step 3: Normalize: (x - mean) / sqrt(variance + eps)
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64>[]} : (f32) -> tensor<6x7x1x1xf32>
