  %variance = stablehlo.divide %var_sum_reshaped, %count : tensor<6x7x1x1xf32>

  % variance_bcast = "stablehlo.broadcast_in_dim"(%variance) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<6x7x1x1xf32>) -> tensor<6x7x8x8xf32>

  % eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<6x7x8x8xf32>

  // Compute variance + eps
  %var_plus_eps = stablehlo.add %variance_bcast, %eps_bcast : tensor<6x7x8x8xf32>

  // Compute sqrt(variance + eps)
  %std = stablehlo.sqrt %var_plus_eps : tensor<6x7x8x8xf32>

