  // For ConvTranspose2d with stride=2, padding=1, output_padding=1
  // We need to use lhs_dilation=2 and appropriate padding
  // Input: (6, 7, 6, 6) in NCHW format
  // Weight: (7, 7, 3, 3) in OIHW format (note: ConvTranspose uses I and O swapped)
  // Output should be (6, 7, 12, 12)

  // For transposed convolution with stride=2, padding=1, output_padding=1:
  // output_size = (input_size - 1) * stride - 2 * padding + kernel_size + output_padding
  // output_size = (6 - 1) * 2 - 2 * 1 + 3 + 1 = 10 - 2 + 3 + 1 = 12 ✓

  // In StableHLO convolution for transposed conv:
  // - lhs_dilation = [stride, stride] = [2, 2]
  // - rhs_dilation = [1, 1]
  // - padding needs to account for the transposed nature
  // For transposed conv: padding = [kernel_size - padding - 1, kernel_size - padding - 1]
  // padding = [3 - 1 - 1, 3 - 1 - 1] = [1, 1]

  %conv = "stablehlo.convolution"(%arg2, %arg0) {
    window_strides = array<i64: 1, 1>,
    padding = dense<[[1, 1], [1, 1]]> : tensor<2x2xi64>,
    lhs_dilation = array<i64: 2, 2>,
    rhs_dilation = array<i64: 1, 1>,
    dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
    feature_group_count = 1 : i64,
    batch_group_count = 1 : i64
  } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

  // Add bias: broadcast bias to (6, 7, 12, 12)
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {
    broadcast_dimensions = array<i64: 1>
  } : (tensor<7xf32>) -> tensor<6x7x12x12xf32>

  %conv_biased = stablehlo.add %conv, %bias_bcast : tensor<6x7x12x12xf32>

  // Mish activation: x * tanh(softplus(x)) = x * tanh(log(1 + exp(x)))
  // softplus(x) = log(1 + exp(x))
  %exp_x = stablehlo.exponential %conv_biased : tensor<6x7x12x12xf32>
  %one = stablehlo.constant dense<1.0> : tensor<6x7x12x12xf32>
  %one_plus_exp = stablehlo.add %one, %exp_x : tensor<6x7x12x12xf32>
  %softplus = stablehlo.log %one_plus_exp : tensor<6x7x12x12xf32>
  %tanh_softplus = stablehlo.tanh %softplus : tensor<6x7x12x12xf32>
  %mish = stablehlo.multiply %conv_biased, %tanh_softplus : tensor<6x7x12x12xf32>

  // Add 0.5
  %add_val = stablehlo.constant dense<0.5> : tensor<6x7x12x12xf32>
  %after_add = stablehlo.add %mish, %add_val : tensor<6x7x12x12xf32>

  // Hardtanh: clamp to [-1, 1]
  %neg_one = stablehlo.constant dense<-1.0> : tensor<6x7x12x12xf32>
  %one_const = stablehlo.constant dense<1.0> : tensor<6x7x12x12xf32>

  %cmp_lower = "stablehlo.compare"(%after_add, %neg_one) {
    comparison_direction = #stablehlo<comparison_direction LT>,
    compare_type = #stablehlo<comparison_type FLOAT>
  } : (tensor<6x7x12x12xf32>, tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xi1>

  %clamped_lower = "stablehlo.select"(%cmp_lower, %neg_one, %after_add) : 
    (tensor<6x7x12x12xi1>, tensor<6x7x12x12xf32>, tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xf32>

  %cmp_upper = "stablehlo.compare"(%clamped_lower, %one_const) {
    comparison_direction = #stablehlo<comparison_direction GT>,
    compare_type = #stablehlo<comparison_type FLOAT>
  } : (tensor<6x7x12x12xf32>, tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xi1>

  %hardtanh = "stablehlo.select"(%cmp_upper, %one_const, %clamped_lower) : 
    (tensor<6x7x12x12xi1>, tensor<6x7x12x12xf32>, tensor<6x7x12x12xf32>) -> tensor<6x7x12x12xf32>

  // Scale by 2
  %scale = stablehlo.constant dense<2.0> : tensor<6x7x12x12xf32>
  %result = stablehlo.multiply %hardtanh, %scale : tensor<6x7x12x12xf32>

