    // output_size = (input_size - 1) * stride - 2*padding + kernel + output_padding
    //             = (6 - 1) * 2 - 2*1 + 3 + 1 = 10 - 2 + 3 + 1 = 12
    %conv = "stablehlo.convolution"(%arg3, %arg1) {
      window_strides = array<i64: 1, 1>,
      padding = dense<[[1, 2], [1, 2]]> : tensor<2x2xi64>,
      lhs_dilation = array<i64: 2, 2>,
      rhs_dilation = array<i64: 1, 1>,
      dimension_numbers = #stablehlo.conv<[b, f, 0, 1]x[o, i, 0, 1]->[b, f, 0, 1]>,
      feature_group_count = 1 : i64,
      batch_group_count = 1 : i64
    } : (tensor<6x7x6x6xf32>, tensor<7x7x3x3xf32>) -> tensor<6x7x12x12xf32>

    // Broadcast bias from shape (7, 1, 1) to (1, 7, 1, 1) then to (6, 7, 12, 12)
    %bias_reshaped = "stablehlo.broadcast_in_dim"(%arg2) {
      broadcast_dimensions = array<i64: 1>
    } : (tensor<7xf32>) -> tensor<1x7x1x1xf32>

    %bias_expanded = "stablehlo.broadcast_in_dim"(%bias_reshaped) {
      broadcast_dimensions = array<i64: 0, 1, 2, 3>
    } : (tensor<1x7x1x1xf32>) -> tensor<6x7x12x12xf32>

    // Add bias
    %add_bias = stablehlo.add %conv, %bias_expanded : tensor<6x7x12x12xf32>

    // Clamp to [0, 1]
    %c0 = stablehlo.constant dense<0.0> : tensor<f32>
    %c1 = stablehlo.constant dense<1.0> : tensor<f32>
    %c0_bcast = "stablehlo.broadcast_in_dim"(%c0) {
      broadcast_dimensions = array<i64>
    } : (tensor<f32>) -> tensor<6x7x12x12xf32>
    %c1_bcast = "stablehlo.broadcast_in_dim"(%c1) {
      broadcast_dimensions = array<i64>
    } : (tensor<f32>) -> tensor<6x7x12x12xf32>

    %clamp1 = stablehlo.maximum %add_bias, %c0_bcast : tensor<6x7x12x12xf32>
    %clamp1_final = stablehlo.minimum %clamp1, %c1_bcast : tensor<6x7x12x12xf32>

    // Multiply by scaling factor 2.0
    %scale = stablehlo.constant dense<2.0> : tensor<f32>
    %scale_bcast = "stablehlo.broadcast_in_dim"(%scale) {
      broadcast_dimensions = array<i64>
    } : (tensor<f32>) -> tensor<6x7x12x12xf32>
    %scaled = stablehlo.multiply %clamp1_final, %scale_bcast : tensor<6x7x12x12xf32>

    // Clamp to [0, 1] again
    %clamp2 = stablehlo.maximum %scaled, %c0_bcast : tensor<6x7x12x12xf32>
    %clamp2_final = stablehlo.minimum %clamp2, %c1_bcast : tensor<6x7x12x12xf32>

    // Divide by scaling factor 2.0
    %result = stablehlo.divide %clamp2_final, %scale_bcast : tensor<6x7x12x12xf32>

    return %result : tensor<6x7x12x12xf32>
  }
}

func.func @main(%arg0: tensor<6x7x7xf32>, %arg1: tensor<6x7x7xf32>, %arg2: tensor<16x6x7x7xf32>) -> tensor<16x6x7x7xf32> {
  // arg0 = ln.weight (6x7x7)
  // arg1 = ln.bias (6x7x7)
  // arg2 = input x (16x6x7x7)

  // Compute mean over dimensions [1, 2, 3]
  %init_mean = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = "stablehlo.reduce"(%arg2, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1, 2, 3>} : (tensor<16x6x7x7xf32>, tensor<f32>) -> tensor<16xf32>

  // Number of elements in normalized shape: 6 * 7 * 7 = 294
  %num_elements = stablehlo.constant dense<294.0> : tensor<f32>
  %num_elements_bcast = "stablehlo.broadcast_in_dim"(%num_elements) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<16xf32>
  %mean = stablehlo.divide %sum, %num_elements_bcast : tensor<16xf32>

  // Broadcast mean to input shape for subtraction
  %mean_bcast = "stablehlo.broadcast_in_dim"(%mean) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x6x7x7xf32>

  // Compute x - mean
  %x_minus_mean = stablehlo.subtract %arg2, %mean_bcast : tensor<16x6x7x7xf32>

  // Compute variance: reduce((x - mean)^2)
  %x_minus_mean_sq = stablehlo.multiply %x_minus_mean, %x_minus_mean : tensor<16x6x7x7xf32>
  %init_var = stablehlo.constant dense<0.0> : tensor<f32>
  %var_sum = "stablehlo.reduce"(%x_minus_mean_sq, %init_var) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %s = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 1, 2, 3>} : (tensor<16x6x7x7xf32>, tensor<f32>) -> tensor<16xf32>

  %variance = stablehlo.divide %var_sum, %num_elements_bcast : tensor<16xf32>

  % epsilon = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %epsilon_bcast = "stablehlo.broadcast_in_dim"(%epsilon) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<16xf32>
  %var_plus_eps = stablehlo.add %variance, %epsilon_bcast : tensor<16xf32>

  // Compute sqrt(variance + eps)
  %std = stablehlo.sqrt %var_plus_eps : tensor<16xf32>

  % std_bcast = "stablehlo.broadcast_in_dim"(%std) {broadcast_dimensions = array<i64: 0>} : (tensor<16xf32>) -> tensor<16x6x7x7xf32>

  // Normalize: (x - mean) / std
  %normalized = stablehlo.divide %x_minus_mean, %std_bcast : tensor<16x6x7x7xf32>

  // Scale: normalized * weight
  %weight_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<6x7x7xf32>) -> tensor<16x6x7x7xf32>
  %scaled = stablehlo.multiply %normalized, %weight_bcast : tensor<16x6x7x7xf32>

  // Shift: scaled + bias
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<6x7x7xf32>) -> tensor<16x6x7x7xf32>
  %result = stablehlo.add %scaled, %bias_bcast : tensor<16x6x7x7xf32>

  return %result : tensor<16x6x7x7xf32>
}

func.func @main(%arg0: tensor<6x7x7xf32>, %arg1: tensor<6x7x7xf32>, %arg2: tensor<16x6x7x7xf32>) -> tensor<16x6x7x7xf32> {
  %cst = stablehlo.constant dense<1.0> : tensor<f32>
  %cst_0 = stablehlo.constant dense<0.0> : tensor<f32>
  %cst_1 = stablehlo.constant dense<1.0E-5> : tensor<f32>

  // Reshape input from [16, 6, 7, 7] to [16, 294] for layer norm computation
  // where 294 = 6 * 7 * 7
  %shape = stablehlo.constant dense<[16, 294]> : tensor<2xi32>
  %reshaped = stablehlo.reshape %arg2 : (tensor<16x6x7x7xf32>) -> tensor<16x294xf32>

  // Compute mean over the last dimension (294)
  %mean = stablehlo.reduce %reshaped init: %cst_0 dimensions = [1] (%lhs: tensor<f32>, %rhs: tensor<f32>) {
    %add = stablehlo.add %lhs, %rhs : tensor<f32>
    stablehlo.return %add : tensor<f32>
  } : (tensor<16x294xf32>, tensor<f32>) -> tensor<16xf32>

  // Divide by 294 to get actual mean
  %num_features = stablehlo.constant dense<294.0> : tensor<f32>
  %mean_broadcasted = stablehlo.broadcast_in_dim %mean, dims = [0] : (tensor<16xf32>) -> tensor<16x294xf32>
  %mean_value = stablehlo.divide %mean_broadcasted, stablehlo.broadcast_in_dim %num_features, dims = [] : (tensor<f32>) -> tensor<16x294xf32> : (tensor<16x294xf32>, tensor<16x294xf32>) -> tensor<16x294xf32>

  // Compute variance: E[(x - mean)^2]
  %centered = stablehlo.subtract %reshaped, %mean_value : tensor<16x294xf32>
  %squared = stablehlo.multiply %centered, %centered : tensor<16x294xf32>
  %variance = stablehlo.reduce %squared init: %cst_0 dimensions = [1] (%lhs: tensor<f32>, %rhs: tensor<f32>) {
    %add = stablehlo.add %lhs, %rhs : tensor<f32>
    stablehlo.return %add : tensor<f32>
  } : (tensor<16x294xf32>, tensor<f32>) -> tensor<16xf32>

  %variance_value = stablehlo.divide %variance, stablehlo.broadcast_in_dim %num_features, dims = [] : (tensor<f32>) -> tensor<16x294xf32> : (tensor<16x294xf32>, tensor<16x294xf32>) -> tensor<16x294xf32>

  // Compute standard deviation: sqrt(variance + eps)
  %eps_broadcasted = stablehlo.broadcast_in_dim %cst_1, dims = [] : (tensor<f32>) -> tensor<16x294xf32>
  %var_plus_eps = stablehlo.add %variance_value, %eps_broadcasted : tensor<16x294xf32>
  %std = stablehlo.sqrt %var_plus_eps : tensor<16x294xf32>

  // Normalize: (x - mean) / std
  %normalized = stablehlo.divide %centered, %std : tensor<16x294xf32>

  // Reshape weight and bias from [6, 7, 7] to [294]
  %weight_reshaped = stablehlo.reshape %arg0 : (tensor<6x7x7xf32>) -> tensor<294xf32>
  %bias_reshaped = stablehlo.reshape %arg1 : (tensor<6x7x7xf32>) -> tensor<294xf32>

  // Broadcast weight and bias to [16, 294]
  %weight_broadcasted = stablehlo.broadcast_in_dim %weight_reshaped, dims = [1] : (tensor<294xf32>) -> tensor<16x294xf32>
  %bias_broadcasted = stablehlo.broadcast_in_dim %bias_reshaped, dims = [1] : (tensor<294xf32>) -> tensor<16x294xf32>

  // Apply affine transformation: y = weight * normalized + bias
  %scaled = stablehlo.multiply %normalized, %weight_broadcasted : tensor<16x294xf32>
  %output_flat = stablehlo.add %scaled, %bias_broadcasted : tensor<16x294xf32>

  // Reshape back to [16, 6, 7, 7]
  %output = stablehlo.reshape %output_flat : (tensor<16x294xf32>) -> tensor<16x6x7x7xf32>

  return %output : tensor<16x6x7x7xf32>
}

func.func @main(%arg0: tensor<6x7x7xf32>, %arg1: tensor<6x7x7xf32>, %arg2: tensor<16x6x7x7xf32>) -> tensor<16x6x7x7xf32> {
