  %mean_bcast_full = "stablehlo.broadcast_in_dim"(%mean_bcast) {broadcast_dimensions = array<i64: 0, 1, 2, 3>} : (tensor<16x1x1x1xf32>) -> tensor<16x6x7x7xf32>

  // Compute (x - mean)
  %centered = stablehlo.subtract %arg2, %mean_bcast_full : tensor<16x6x7x7xf32>

  // Compute squared differences
  %sq_diff = stablehlo.multiply %centered, %centered : tensor<16x6x7x7xf32>

