  // Add epsilon to variance
  %eps_bcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<16x6x7x7xf32>
  %var_plus_eps = stablehlo.add %var_bcast_full, %eps_bcast : tensor<16x6x7x7xf32>

  // Compute sqrt(var + eps)
  %std = stablehlo.sqrt %var_plus_eps : tensor<16x6x7x7xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %normalized = stablehlo.divide %centered, %std : tensor<16x6x7x7xf32>

  // Broadcast weight to match input shape
  %weight_bcast = "stablehlo.broadcast_in_dim"(%arg0) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<6x7x7xf32>) -> tensor<16x6x7x7xf32>

  // Scale: normalized * weight
  %scaled = stablehlo.multiply %normalized, %weight_bcast : tensor<16x6x7x7xf32>

  // Broadcast bias to match input shape
  %bias_bcast = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1, 2, 3>} : (tensor<6x7x7xf32>) -> tensor<16x6x7x7xf32>

  // Add bias: scaled + bias
  %result = stablehlo.add %scaled, %bias_bcast : tensor<16x6x7x7xf32>

  return %result : tensor<16x6x7x7xf32>
}

