func.func @main(%arg0: tensor<f32>, %arg1: tensor<16x1x1x1xf32>, %arg2: tensor<f32>, %arg3: tensor<3x16x3x3x3xf32>, %arg4: tensor<16xf32>, %arg5: tensor<6x3x16x7x7xf32>) -> tensor<6x16x15x6x6xf32> {
