  } : (tensor<f32>) -> tensor<6x6x7x7xf32>
  %scaled_scores = stablehlo.multiply %scores, %scale_factor_bcast : tensor<6x6x7x7xf32>

  // Step 3: Apply softmax over the last dimension (sequence dimension)
  // First, find max for numerical stability
  %neg_inf = "stablehlo.constant"() {value = dense<-3.40282347e+38> : tensor<f32>} : () -> tensor<f32>
  %max_scores = "stablehlo.reduce"(%scaled_scores, %neg_inf) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %max_val = stablehlo.maximum %a, %b : tensor<f32>
      "stablehlo.return"(%max_val) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6x6x7xf32>

  // Broadcast max back to original shape
  %max_scores_bcast = "stablehlo.broadcast_in_dim"(%max_scores) {
    broadcast_dimensions = array<i64: 0, 1, 2>
  } : (tensor<6x6x7xf32>) -> tensor<6x6x7x7xf32>

  // Subtract max for stability
  %scores_shifted = stablehlo.subtract %scaled_scores, %max_scores_bcast : tensor<6x6x7x7xf32>

  // Compute exp
  %exp_scores = stablehlo.exponential %scores_shifted : tensor<6x6x7x7xf32>

