  %zero = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %sum_exp = "stablehlo.reduce"(%exp_scores, %zero) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %sum_val = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%sum_val) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 3>} : (tensor<6x6x7x7xf32>, tensor<f32>) -> tensor<6x6x7xf32>

