  %sum_exp_bcast = "stablehlo.broadcast_in_dim"(%sum_exp) {
    broadcast_dimensions = array<i64: 0, 1, 2>
  } : (tensor<6x6x7xf32>) -> tensor<6x6x7x7xf32>

  // Compute softmax: exp(x) / sum(exp(x))
  %attn_weights = stablehlo.divide %exp_scores, %sum_exp_bcast : tensor<6x6x7x7xf32>

  // Step 4: Apply attention to values
  // attn_weights: [6, 6, 7, 7], V: [6, 6, 7, 8]
  // Result: [6, 6, 7, 8]
  %output = "stablehlo.dot_general"(%attn_weights, %arg2) {
