  % is_negative = "stablehlo.compare"(%gn_out_with_bias, %zero_f32) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type FLOAT>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xi1>

  % negative_slope = stablehlo.constant dense<0.01> : tensor<16x16xf32>
  % scaled_negative = stablehlo.multiply %gn_out_with_bias, %negative_slope : tensor<16x16xf32>

  % leaky_relu_out = "stablehlo.select"(%is_negative, %scaled_negative, %gn_out_with_bias) : (tensor<16x16xi1>, tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // x = x + x
  % result = stablehlo.add %leaky_relu_out, %leaky_relu_out : tensor<16x16xf32>

  return %result : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<12x12xf32>, %arg1: tensor<12x12xf32>) -> tensor<f32> {
  // Compute KL divergence: sum(targets * (log(targets) - log(predictions))) / batch_size

  // Step 1: Compute log(predictions)
  %log_predictions = stablehlo.log(%arg0) : tensor<12x12xf32>

  // Step 2: Compute log(targets)
  %log_targets = stablehlo.log(%arg1) : tensor<12x12xf32>

  // Step 3: Compute log(targets) - log(predictions)
  %log_ratio = stablehlo.subtract(%log_targets, %log_predictions) : tensor<12x12xf32>

  // Step 4: Compute targets * (log(targets) - log(predictions))
  %weighted = stablehlo.multiply(%arg1, %log_ratio) : tensor<12x12xf32>

  // Step 5: Sum all elements using reduce
  %init = stablehlo.constant dense<0.0> : tensor<f32>
  %sum = stablehlo.reduce(%weighted init: %init) across dimensions = [0, 1] : (tensor<12x12xf32>, tensor<f32>) -> tensor<f32>
    (%arg_block_0: tensor<f32>, %arg_block_1: tensor<f32>) {
      %add_result = stablehlo.add(%arg_block_0, %arg_block_1) : tensor<f32>
      stablehlo.return(%add_result) : tensor<f32>
    }

  // Step 6: Divide by batch size (12)
  %batch_size = stablehlo.constant dense<12.0> : tensor<f32>
  %result = stablehlo.divide(%sum, %batch_size) : tensor<f32>

  return %result : tensor<f32>
}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // Step 1: Linear layer - fc(x) = x @ fc.weight.T + fc.bias
  // arg4 is (16, 16), arg0 is (16, 16) weight, arg1 is (16,) bias
  // We need to compute arg4 @ arg0.T
  %0 = "stablehlo.dot_general"(%arg4, %arg0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [1]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias
  %1 = "stablehlo.broadcast_in_dim"(%arg1) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %2 = stablehlo.add %0, %1 : tensor<16x16xf32>

  // Step 2: Group Normalization with 16 groups on 16 channels
  // Reshape to (batch=16, groups=16, channels_per_group=1)
  %3 = stablehlo.reshape %2 : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean over the last dimension (channels_per_group)
  %4 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %5 = "stablehlo.reduce"(%3, %4) ({
    ^bb0(%arg5: tensor<f32>, %arg6: tensor<f32>):
      %sum = stablehlo.add %arg5, %arg6 : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Divide by group size (1) to get mean
  %6 = "stablehlo.constant"() {value = dense<1.0> : tensor<f32>} : () -> tensor<f32>
  %7 = stablehlo.divide %5, %6 : tensor<16x16xf32>

  // Broadcast mean back
  %8 = "stablehlo.broadcast_in_dim"(%7) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Center: x - mean
  %9 = stablehlo.subtract %3, %8 : tensor<16x16x1xf32>

  // Compute variance
  %10 = stablehlo.multiply %9, %9 : tensor<16x16x1xf32>
  %11 = "stablehlo.reduce"(%10, %4) ({
    ^bb0(%arg5: tensor<f32>, %arg6: tensor<f32>):
      %sum = stablehlo.add %arg5, %arg6 : tensor<f32>
      "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Divide by group size (1)
  %12 = stablehlo.divide %11, %6 : tensor<16x16xf32>

  // Add epsilon
  %13 = "stablehlo.constant"() {value = dense<1.0e-5> : tensor<f32>} : () -> tensor<f32>
  %14 = "stablehlo.broadcast_in_dim"(%13) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<16x16xf32>
  %15 = stablehlo.add %12, %14 : tensor<16x16xf32>

  // Compute sqrt(var + eps)
  %16 = stablehlo.sqrt %15 : tensor<16x16xf32>

  // Broadcast for normalization
  %17 = "stablehlo.broadcast_in_dim"(%16) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %18 = stablehlo.divide %9, %17 : tensor<16x16x1xf32>

  // Reshape back to (16, 16)
  %19 = stablehlo.reshape %18 : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply scale (gn.weight) and shift (gn.bias)
  %20 = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %21 = stablehlo.multiply %19, %20 : tensor<16x16xf32>

  %22 = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %23 = stablehlo.add %21, %22 : tensor<16x16xf32>

  // Step 3: LeakyReLU with negative_slope=0.01
  %24 = "stablehlo.constant"() {value = dense<0.0> : tensor<f32>} : () -> tensor<f32>
  %25 = "stablehlo.broadcast_in_dim"(%24) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<16x16xf32>
  %26 = "stablehlo.compare"(%23, %25) {comparison_direction = #stablehlo<comparison_direction GE>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xi1>

  %27 = "stablehlo.constant"() {value = dense<0.01> : tensor<f32>} : () -> tensor<f32>
  %28 = "stablehlo.broadcast_in_dim"(%27) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<16x16xf32>
  %29 = stablehlo.multiply %23, %28 : tensor<16x16xf32>

  %30 = "stablehlo.select"(%26, %23, %29) : (tensor<16x16xi1>, tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Step 4: Element-wise sum: x + x
  %31 = stablehlo.add %30, %30 : tensor<16x16xf32>

  return %31 : tensor<16x16xf32>
}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
