  %4 = stablehlo.reshape %3 : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean and variance per group
  // Mean over the last dimension (channels_per_group)
  %5 = stablehlo.constant dense<0.0> : tensor<f32>
  %6 = "stablehlo.reduce"(%4, %5) ({ ^bb0(%a: tensor<f32>, %b: tensor<f32>):
