  %8 = "stablehlo.broadcast_in_dim"(%7) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<16x16xf32>
  %9 = stablehlo.divide %6, %8 : tensor<16x16xf32>

  // Reshape mean back to (16, 16, 1) for broadcasting
  %10 = stablehlo.reshape %9 : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute variance: E[(x - mean)^2]
  %11 = stablehlo.subtract %4, %10 : tensor<16x16x1xf32>
  %12 = stablehlo.multiply %11, %11 : tensor<16x16x1xf32>

  %13 = stablehlo.constant dense<0.0> : tensor<f32>
  %14 = "stablehlo.reduce"(%12, %13) ({ ^bb0(%a: tensor<f32>, %b: tensor<f32>):
    %sum = stablehlo.add %a, %b : tensor<f32>
    "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  %15 = stablehlo.divide %14, %8 : tensor<16x16xf32>
  %16 = stablehlo.reshape %15 : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

