  %17 = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %18 = "stablehlo.broadcast_in_dim"(%17) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<16x16x1xf32>
  %19 = stablehlo.add %16, %18 : tensor<16x16x1xf32>

  // Compute sqrt(variance + eps)
  %20 = stablehlo.sqrt %19 : tensor<16x16x1xf32>

  // Normalize: (x - mean) / sqrt(variance + eps)
  %21 = stablehlo.divide %11, %20 : tensor<16x16x1xf32>

