}

func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // Step 1: Linear layer - x = fc(x)
  // x @ fc.weight.T + fc.bias
  // arg4 is (16, 16), arg0 is (16, 16), arg1 is (16,)
  %0 = "stablehlo.dot_general"(%arg4, %arg0) {dot_dimension_numbers = #stablehlo.dot<lhs_contracting_dimensions = [1], rhs_contracting_dimensions = [0]>} : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

