func.func @main(%arg0: tensor<16x16xf32>, %arg1: tensor<16xf32>, %arg2: tensor<16xf32>, %arg3: tensor<16xf32>, %arg4: tensor<16x16xf32>) -> tensor<16x16xf32> {
  // arg0: fc.weight (16x16)
  // arg1: fc.bias (16)
  // arg2: gn.weight (16)
  // arg3: gn.bias (16)
  // arg4: input x (16x16)

  // Step 1: Linear layer - x = fc(x)
  // x @ fc.weight.T + fc.bias
  // arg4 is (16x16), arg0 is (16x16)
  // We need to compute arg4 @ arg0.T
  %0 = stablehlo.transpose %arg0, dims = [1, 0] : (tensor<16x16xf32>) -> tensor<16x16xf32>
  %1 = stablehlo.dot_general %arg4, %0, contracting_dims = [1], [0] : (tensor<16x16xf32>, tensor<16x16xf32>) -> tensor<16x16xf32>

  // Add bias
  %bias_broadcast = stablehlo.broadcast_in_dim %arg1, broadcast_dims = [1] : (tensor<16xf32>) -> tensor<16x16xf32>
  %2 = stablehlo.add %1, %bias_broadcast : tensor<16x16xf32>

  // Step 2: Group Normalization with num_groups=16, num_channels=16
  // This means each group has 1 channel
  // Reshape to (batch_size, num_groups, channels_per_group) = (16, 16, 1)
  %3 = stablehlo.reshape %2 : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute mean and variance per group
  // Mean over the last dimension (channels_per_group)
  %4 = stablehlo.reduce %3 init with %cst_zero : tensor<16x16x1xf32> across dimensions = [2] : (tensor<16x16x1xf32>, f32) -> tensor<16x16xf32>
  {
    ^bb0(%arg5: f32, %arg6: f32):
      %sum = stablehlo.add %arg5, %arg6 : f32
      stablehlo.return %sum : f32
  }

  // Divide by channels_per_group (which is 1)
  %cst_one = stablehlo.constant dense<1.0> : tensor<f32>
  %cst_one_broadcast = stablehlo.broadcast_in_dim %cst_one, broadcast_dims = [] : (tensor<f32>) -> tensor<16x16xf32>
  %mean = stablehlo.divide %4, %cst_one_broadcast : tensor<16x16xf32>

  // Reshape mean back to (16, 16, 1) for broadcasting
  %mean_reshaped = stablehlo.reshape %mean : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute variance: E[(x - mean)^2]
  %centered = stablehlo.subtract %3, %mean_reshaped : tensor<16x16x1xf32>
  %squared = stablehlo.multiply %centered, %centered : tensor<16x16x1xf32>

  %var_sum = stablehlo.reduce %squared init with %cst_zero : tensor<16x16x1xf32> across dimensions = [2] : (tensor<16x16x1xf32>, f32) -> tensor<16x16xf32>
  {
    ^bb0(%arg5: f32, %arg6: f32):
      %sum = stablehlo.add %arg5, %arg6 : f32
      stablehlo.return %sum : f32
  }

  %variance = stablehlo.divide %var_sum, %cst_one_broadcast : tensor<16x16xf32>

  // Reshape variance back to (16, 16, 1)
  %var_reshaped = stablehlo.reshape %variance : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Normalize: (x - mean) / sqrt(var + eps)
  %cst_eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %cst_eps_broadcast = stablehlo.broadcast_in_dim %cst_eps, broadcast_dims = [] : (tensor<f32>) -> tensor<16x16x1xf32>
  %var_plus_eps = stablehlo.add %var_reshaped, %cst_eps_broadcast : tensor<16x16x1xf32>
  %std = stablehlo.sqrt %var_plus_eps : tensor<16x16x1xf32>
  %normalized = stablehlo.divide %centered, %std : tensor<16x16x1xf32>

  // Reshape back to (16, 16)
  %normalized_flat = stablehlo.reshape %normalized : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply weight and bias
  %weight_broadcast = stablehlo.broadcast_in_dim %arg2, broadcast_dims = [1] : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_gn_broadcast = stablehlo.broadcast_in_dim %arg3, broadcast_dims = [1] : (tensor<16xf32>) -> tensor<16x16xf32>
  %5 = stablehlo.multiply %normalized_flat, %weight_broadcast : tensor<16x16xf32>
  %6 = stablehlo.add %5, %bias_gn_broadcast : tensor<16x16xf32>

  // Step 3: LeakyReLU with negative_slope=0.01
  %cst_zero_scalar = stablehlo.constant dense<0.0> : tensor<f32>
