  // Compute mean over the last dimension (group_size dimension)
  %zero = stablehlo.constant dense<0.0> : tensor<f32>
  %mean = "stablehlo.reduce"(%reshaped, %zero) ({ ^bb0(%a: tensor<f32>, %b: tensor<f32>):
    %sum = stablehlo.add %a, %b : tensor<f32>
    "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Divide by group_size (1) to get mean
  %group_size = stablehlo.constant dense<1.0> : tensor<f32>
  %mean_normalized = stablehlo.divide %mean, %group_size : tensor<16x16xf32>

  // Broadcast mean back to original shape
  %mean_broadcast = "stablehlo.broadcast_in_dim"(%mean_normalized) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Compute centered values
  %centered = stablehlo.subtract %reshaped, %mean_broadcast : tensor<16x16x1xf32>

  // Compute variance
  %centered_sq = stablehlo.multiply %centered, %centered : tensor<16x16x1xf32>
  %var = "stablehlo.reduce"(%centered_sq, %zero) ({ ^bb0(%a: tensor<f32>, %b: tensor<f32>):
    %sum = stablehlo.add %a, %b : tensor<f32>
    "stablehlo.return"(%sum) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2>} : (tensor<16x16x1xf32>, tensor<f32>) -> tensor<16x16xf32>

  // Divide by group_size to get variance
  %var_normalized = stablehlo.divide %var, %group_size : tensor<16x16xf32>

  // Add epsilon for numerical stability
  %eps = stablehlo.constant dense<1.0e-5> : tensor<f32>
  %eps_broadcast = "stablehlo.broadcast_in_dim"(%eps) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<16x16xf32>
  %var_with_eps = stablehlo.add %var_normalized, %eps_broadcast : tensor<16x16xf32>

  // Compute standard deviation
  %std = stablehlo.sqrt %var_with_eps : tensor<16x16xf32>

  // Broadcast std back to original shape
  %std_broadcast = "stablehlo.broadcast_in_dim"(%std) {broadcast_dimensions = array<i64: 0, 1>} : (tensor<16x16xf32>) -> tensor<16x16x1xf32>

  // Normalize
  %normalized = stablehlo.divide %centered, %std_broadcast : tensor<16x16x1xf32>

  // Reshape back to (16, 16)
  %normalized_reshaped = stablehlo.reshape %normalized : (tensor<16x16x1xf32>) -> tensor<16x16xf32>

  // Apply weight and bias
  %weight_broadcast = "stablehlo.broadcast_in_dim"(%arg2) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>
  %bias_broadcast_gn = "stablehlo.broadcast_in_dim"(%arg3) {broadcast_dimensions = array<i64: 1>} : (tensor<16xf32>) -> tensor<16x16xf32>

  %scaled = stablehlo.multiply %normalized_reshaped, %weight_broadcast : tensor<16x16xf32>
  %group_norm_result = stablehlo.add %scaled, %bias_broadcast_gn : tensor<16x16xf32>

  // Step 3: HardTanh - clamp to [-2.0, 2.0]
  %hardtanh_min = stablehlo.constant dense<-2.0> : tensor<f32>
  %hardtanh_max = stablehlo.constant dense<2.0> : tensor<f32>

  %hardtanh_min_broadcast = "stablehlo.broadcast_in_dim"(%hardtanh_min) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<16x16xf32>
  %hardtanh_max_broadcast = "stablehlo.broadcast_in_dim"(%hardtanh_max) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<16x16xf32>

  %clamped_min = stablehlo.maximum %group_norm_result, %hardtanh_min_broadcast : tensor<16x16xf32>
  %result = stablehlo.minimum %clamped_min, %hardtanh_max_broadcast : tensor<16x16xf32>

  return %result : tensor<16x16xf32>
}

