  %result = "stablehlo.select"(%comparison, %one_broadcast, %zero_broadcast) : (tensor<8x3xi1>, tensor<8x3xf32>, tensor<8x3xf32>) -> tensor<8x3xf32>

  return %result : tensor<8x3xf32>
}

func.func @main(%idx: tensor<8xi32>) -> tensor<8x3xf32> {
