  %c0_f32 = stablehlo.constant dense<0.0> : tensor<f32>

  // Create a tensor of shape [8, 3] where each row contains [0, 1, 2]
  %iota = "stablehlo.iota"() {iota_dimension = 1 : i64} : () -> tensor<8x3xi32>

