  %idx_lt_3 = "stablehlo.compare"(%idx, %c3_i32) {comparison_direction = #stablehlo<comparison_direction LT>, compare_type = #stablehlo<comparison_type SIGNED>} : (tensor<8xi32>, tensor<i32>) -> tensor<8xi1>
