func.func @main(%arg0: tensor<16x1x1x1xf32>, %arg1: tensor<16x8x3x3x3xf32>, %arg2: tensor<16xf32>, %arg3: tensor<6x8x16x7x7xf32>) -> tensor<6x1x1x1xf32> {
