  %sum_spatial = "stablehlo.reduce"(%conv_biased, %init_mean) ({
    ^bb0(%a: tensor<f32>, %b: tensor<f32>):
      %add_result = stablehlo.add %a, %b : tensor<f32>
      "stablehlo.return"(%add_result) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<6x6x4x4xf32>, tensor<f32>) -> tensor<6x6xf32>

  // Divide by spatial size (4 * 4 = 16)
  %spatial_size = stablehlo.constant dense<16.0> : tensor<f32>
  %mean = stablehlo.divide %sum_spatial, %spatial_size : tensor<6x6xf32>

