  %multiplier_broadcast = "stablehlo.broadcast_in_dim"(%multiplier) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x7x13x13xf32>
  %after_multiply = stablehlo.multiply %after_bias, %multiplier_broadcast : tensor<16x7x13x13xf32>

  // First global average pooling: reduce over dimensions 2 and 3, keep dims
