      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<16x7x13x13xf32>, tensor<f32>) -> tensor<16x7xf32>

  // Reshape to add back dimensions for keepdim
  %after_first_pool = stablehlo.reshape %sum_first : (tensor<16x7xf32>) -> tensor<16x7x1x1xf32>

  // Divide by the number of elements (13 * 13 = 169)
  %count_first = stablehlo.constant dense<169.0> : tensor<f32>
  %count_first_broadcast = "stablehlo.broadcast_in_dim"(%count_first) {broadcast_dimensions = array<i64: >} : (tensor<f32>) -> tensor<16x7x1x1xf32>
  %after_first_avg = stablehlo.divide %after_first_pool, %count_first_broadcast : tensor<16x7x1x1xf32>

  // Second global average pooling: reduce over dimensions 2 and 3 again (which are now size 1)
