      "stablehlo.return"(%s) : (tensor<f32>) -> ()
  }) {dimensions = array<i64: 2, 3>} : (tensor<16x7x1x1xf32>, tensor<f32>) -> tensor<16x7xf32>

  // Reshape back to keep dimensions
  %result = stablehlo.reshape %sum_second : (tensor<16x7xf32>) -> tensor<16x7x1x1xf32>

  return %result : tensor<16x7x1x1xf32>
}

