  %count1 = stablehlo.constant dense<225.0> : tensor<f32>
  %count1_bcast = "stablehlo.broadcast_in_dim"(%count1) {broadcast_dimensions = array<i64>} : (tensor<f32>) -> tensor<16x7x1x1xf32>
  %mean1 = stablehlo.divide %pooled1_reshaped, %count1_bcast : tensor<16x7x1x1xf32>

